class Solution { static final long MOD=1_000_000_007;private long power(long base,long exponent){long result=1;while(exponent>0){if((exponent&1)==1)result=result*base%MOD;base=base*base%MOD;exponent>>=1;}return result;}public int minNonZeroProduct(int p){long maximum=(power(2,p)-1+MOD)%MOD;long exponent=(1L<<(p-1))-1;return (int)(maximum*power((maximum-1+MOD)%MOD,exponent)%MOD);} }
